import{_ as a,C as o,o as r,c as i,E as n,a2 as s}from"./chunks/framework.BOeh4kYD.js";const y=JSON.parse('{"title":"Task Completion Does Not Prove Team Reliability","description":"","frontmatter":{"title":"Task Completion Does Not Prove Team Reliability","date":"2026-09-14","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"在声称多智能体团队可靠之前，为什么必须分别证明任务分配、顺序约束、互斥安全与交接连续性，而不能只看总体任务成功？","summary":"Aggregate success compresses duplicate allocation, ordering violations, resource contention, and broken handoffs into one number. Multi-agent reliability should remain a separately evidenced coordination vector whose critical weak dimensions cannot be averaged away.","sources":["research/analysis/Q-20260914-02-coordination-reliability-vector.md"],"item_id":"Q-20260914-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-14-task-completion-not-team-reliability-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-09-14-task-completion-not-team-reliability.md","filePath":"en/industry/2026-09-14-task-completion-not-team-reliability.md","lastUpdated":1789388081000}'),c={name:"en/industry/2026-09-14-task-completion-not-team-reliability.md"};function l(d,e,h,u,p,m){const t=o("ArticleCover");return r(),i("div",null,[n(t,{image:"/assets/covers/daily-2026-09-14-task-completion-not-team-reliability-cover.png",kicker:"Industry Architecture · Daily Research",title:"Task Completion Does Not Prove Team Reliability",summary:"Aggregate success compresses duplicate allocation, ordering violations, resource contention, and broken handoffs into one number. Multi-agent reliability should remain a separately evidenced coordination vector whose critical weak dimensions cannot be averaged away.",version:"Q-20260914-02",status:"Daily Runtime V5 · 2026-09-14",languageHref:"/zh/industry/2026-09-14-task-completion-not-team-reliability",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="task-completion-does-not-prove-team-reliability" tabindex="-1">Task Completion Does Not Prove Team Reliability <a class="header-anchor" href="#task-completion-does-not-prove-team-reliability" aria-label="Permalink to &quot;Task Completion Does Not Prove Team Reliability&quot;">​</a></h1><p>Three agents deliver a correct report. The final document says the team succeeded. The trajectory says two agents duplicated the same research, another began synthesis before prerequisite evidence was ready, and the final handoff required manual repair.</p><p>The outcome is correct, but the coordination is not reliable. <strong>Aggregate success proves only that the goal was eventually reached. It does not prove that allocation, ordering, mutual exclusion, and handoff satisfied their distinct operational obligations.</strong></p><h2 id="four-coordination-constructs-are-not-one-ability" tabindex="-1">Four Coordination Constructs Are Not One Ability <a class="header-anchor" href="#four-coordination-constructs-are-not-one-ability" aria-label="Permalink to &quot;Four Coordination Constructs Are Not One Ability&quot;">​</a></h2><p>The same-date Research Object examines CoCoBench, a primary study with 897 oracle-validated executable tasks across 11 multimodal models. It separates coordination into four constructs:</p><ul><li><strong>task allocation</strong> — whether pending work has clear ownership without wasteful duplication;</li><li><strong>sequential ordering</strong> — whether dependent actions begin only after prerequisites close;</li><li><strong>mutual exclusion</strong> — whether exclusive shared resources are serialized;</li><li><strong>handoff</strong> — whether produced state transfers completely and the receiver accepts it.</li></ul><p>These are not four names for one ability. Duplicate allocation wastes capacity. Ordering violations can invalidate downstream work. Exclusion failures can corrupt shared state. Handoff failures can strand responsibility. The same terminal success rate cannot express those differences.</p><p>The study reports construct-specific behavior. A team can allocate well while performing poorly on exclusion, or eventually finish while handling transfers inefficiently.</p><h2 id="a-correct-result-can-hide-a-broken-trajectory" tabindex="-1">A Correct Result Can Hide a Broken Trajectory <a class="header-anchor" href="#a-correct-result-can-hide-a-broken-trajectory" aria-label="Permalink to &quot;A Correct Result Can Hide a Broken Trajectory&quot;">​</a></h2><p>Terminal scoring has a basic blind spot: it checks arrival without checking the route.</p><p>A team may violate ordering and then recover through rework. It may contend for a resource without visible damage in that run. It may lose a handoff and be rescued by another agent. If evaluation inspects only the final file, these operational risks disappear.</p><p>Outcome success remains valuable. It is a result fact and often the user&#39;s primary concern. The error is enlarging it into reliability proof. One correct artifact cannot establish that the same protocol remains safe with more agents, higher concurrency, or irreversible effects.</p><p>CoCoBench&#39;s executable environment and oracle-defined structure make trajectory obligations inspectable, which is stronger than free-form self-assessment. Its household tasks and high-level skill interface, however, do not set quantitative thresholds for enterprise or software teams.</p><h2 id="reliability-must-remain-a-vector" tabindex="-1">Reliability Must Remain a Vector <a class="header-anchor" href="#reliability-must-remain-a-vector" aria-label="Permalink to &quot;Reliability Must Remain a Vector&quot;">​</a></h2><p>A more truthful representation is not one <code>team_reliability=0.84</code>, but a vector:</p><p><code>[allocation, ordering, exclusion, handoff]</code></p><p>Each task-relevant dimension receives at least PASS, FAIL, or UNKNOWN. A construct that does not apply should be explicitly marked, not silently treated as passing. An aggregate can summarize the vector, but it must preserve the underlying results and criticality rules.</p><p>Criticality matters. Failed mutual exclusion in a payment task cannot be averaged away by excellent allocation. An unknown handoff in a medical workflow cannot be replaced by a high completion score. Averages are useful for ranking; they are unsafe as substitutes for hard gates.</p><h2 id="four-inspectable-coordination-contracts" tabindex="-1">Four Inspectable Coordination Contracts <a class="header-anchor" href="#four-inspectable-coordination-contracts" aria-label="Permalink to &quot;Four Inspectable Coordination Contracts&quot;">​</a></h2><p>A runtime can materialize four auditable contracts.</p><p>The <strong>allocation contract</strong> records work-unit identity, owner, lease, duplication policy, and reassignment or abandonment events. It answers who owned what and when.</p><p>The <strong>ordering contract</strong> records the prerequisite graph, evidence that each dependency closed, actual starts and completions, and recovery after violations. It answers whether an action had a legal start condition.</p><p>The <strong>mutual-exclusion contract</strong> records the exclusive resource, holder, acquisition, renewal, and release events, plus concurrent-access detection. It answers whether shared state had one authorized occupant.</p><p>The <strong>handoff contract</strong> records producer, receiver, payload or state identity, offer, acceptance, timeout, and rejection. Producer completion is not receiver acceptance.</p><p>These records are useful because they attach failure to a protocol obligation. Recovery becomes bounded only after the runtime knows which contract failed.</p><h2 id="which-rules-can-be-enforced-mechanically" tabindex="-1">Which Rules Can Be Enforced Mechanically <a class="header-anchor" href="#which-rules-can-be-enforced-mechanically" aria-label="Permalink to &quot;Which Rules Can Be Enforced Mechanically&quot;">​</a></h2><p>When all relevant facts are observable, some obligations can be deterministic. One repository path may have one lease holder. Task B may wait for task A&#39;s verified terminal state. One payment key may bind one active occurrence.</p><p>Other obligations require semantic judgment. A receiver can acknowledge a file without confirming that its contents are sufficient. Ownership can be recorded without proving that the assigned agent is capable. Model or human review still has a role.</p><p>Evidence identities must remain separate. A deterministic event proves that no two holders owned the lock. A semantic review judges handoff completeness. The final artifact proves that a goal was reached. Together they may support reliability; none can replace the others.</p><h2 id="do-not-let-averages-hide-critical-weakness" tabindex="-1">Do Not Let Averages Hide Critical Weakness <a class="header-anchor" href="#do-not-let-averages-hide-critical-weakness" aria-label="Permalink to &quot;Do Not Let Averages Hide Critical Weakness&quot;">​</a></h2><p>The study also reports degradation with larger teams, benefit from centralized state aggregation, and only partial recovery from simple communication. “Communicate more” is not a complete coordination protocol.</p><p>A centralized view improves shared truth but does not enforce exclusion. Messaging can announce a dependency but does not guarantee ordering. A stronger model does not automatically remove every construct-specific weakness. Architecture must decide which obligations belong to state machines, locks, leases, or schedulers and which require generative judgment.</p><p>A practical acceptance rule is straightforward: declare the task-relevant critical constructs, gather evidence for each, reject a reliability claim if any critical item fails, and stop or gather more evidence when one is unknown. Aggregate success becomes an outcome summary only after those gates.</p><h2 id="boundaries-and-open-questions" tabindex="-1">Boundaries and Open Questions <a class="header-anchor" href="#boundaries-and-open-questions" aria-label="Permalink to &quot;Boundaries and Open Questions&quot;">​</a></h2><p>The evidence does not prove that absolute household-task scores transfer to enterprise systems, and it does not decide whether every violation should be retried, compensated, or terminated. Four constructs may not exhaust every domain; authorization updates, version conflicts, and cross-organizational responsibility may require additional dimensions.</p><p>The structural conclusion is bounded but strong: <strong>task completion is an outcome fact; team reliability is evidence about coordination contracts. Any critical obligation with distinct failure semantics must remain visible rather than disappear inside one number.</strong></p><p>Open questions include the minimum event model, how risk selects critical constructs, how UNKNOWN affects terminal state, how admission thresholds change with team size, and whether coordination vectors can be compared across domains.</p><p><strong>Evidence and source:</strong></p><ul><li><a href="https://arxiv.org/abs/2608.28266" target="_blank" rel="noreferrer">CoCoBench: a benchmark for multi-agent coordination</a>, primary research, 2026.</li></ul>',39))])}const b=a(c,[["render",l]]);export{y as __pageData,b as default};
